import {User} from '@app/gen/schemas/user';
import {MenuConfig, MenuItemConfig} from '@common/menus/menu-config';
import {useSettings} from '@ui/settings/use-settings';
import {pickNestedValue} from '@ui/utils/pick-nested-value';
import {useMemo} from 'react';
import {useAuth} from '../auth/use-auth';

export function useCustomMenu(menuOrPosition?: string | MenuConfig) {
  const settings = useSettings();
  const {user, hasPermission, hasRole} = useAuth();

  return useMemo(() => {
    if (!menuOrPosition) {
      return null;
    }

    const sourceMenu =
      typeof menuOrPosition === 'string'
        ? (settings.menus?.find(s => s.id === menuOrPosition) ??
          settings.menus?.find(s => s.positions?.includes(menuOrPosition)))
        : menuOrPosition;

    if (!sourceMenu) {
      return null;
    }

    const menuItems: MenuItemConfig[] = [];

    for (const rawItem of sourceMenu.items ?? []) {
      const item = {...rawItem};
      const hasRoles = (item.roles || []).every(a => hasRole(a));
      const hasPermissions = (item.permissions || []).every(a =>
        hasPermission(a),
      );
      const hasSettings =
        !item.settings ||
        Object.entries(item.settings).every(([key, value]) => {
          return pickNestedValue(key, settings) == value;
        });

      if (
        !item.action ||
        !hasRoles ||
        !hasPermissions ||
        !hasSettings ||
        !subscriptionStatusMatches(item, user)
      ) {
        continue;
      }

      if (user?.id) {
        item.action = item.action.replace(/{currentUser}/g, `${user.id}`);
      }

      menuItems.push(item);
    }

    return {...sourceMenu, items: menuItems};
  }, [hasPermission, settings, menuOrPosition, user, hasRole]);
}

function subscriptionStatusMatches(
  item: MenuItemConfig,
  user?: User | null,
): boolean {
  if (!item.subscriptionStatus) {
    return true;
  }
  const hasActiveSubscription = !!user?.subscription?.active;
  if (item.subscriptionStatus === 'subscribed') {
    return hasActiveSubscription;
  }
  return !hasActiveSubscription;
}
